<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import UiButton from'../../Components/UiButton.vue';import{Head,router}from'@inertiajs/vue3';const p=defineProps({event:Object,photo:Object});function like(){router.post(`/groups/${p.event.id}/photos/${p.photo.id}/like`,{},{preserveScroll:true,onSuccess:()=>router.reload({only:['photo']})})}</script><template><AppShell><Head :title="photo.original_filename"/><div class="lp-page"><PageHeader :eyebrow="event.name" title="Photo viewer"><UiButton variant="secondary" :href="`/groups/${event.id}`">Back to gallery</UiButton><UiButton v-if="photo.download_url" :href="photo.download_url">Download</UiButton></PageHeader><div class="mt-8 grid gap-6 xl:grid-cols-[1fr_320px]"><section class="flex min-h-[50vh] items-center justify-center overflow-hidden rounded-2xl bg-ink p-2 md:p-6"><img :src="photo.url" :alt="photo.caption||photo.original_filename" class="max-h-[75vh] max-w-full object-contain"></section><aside class="space-y-5"><UiCard><p class="text-sm text-slate-500">Uploaded by</p><p class="mt-1 font-semibold">{{photo.uploader||'LensPic participant'}}</p><p v-if="photo.caption" class="mt-4 text-sm leading-6 text-slate-600">{{photo.caption}}</p><button class="btn-secondary mt-5 w-full" @click="like">{{photo.liked?'Favorited':'Add to favorites'}} · {{photo.likes_count}}</button></UiCard><UiCard><h2 class="text-lg font-bold">Comments</h2><p v-if="!photo.comments.length" class="mt-3 text-sm text-slate-500">No comments yet.</p><div v-for="c in photo.comments" :key="c.id" class="mt-4 border-t border-slate-100 pt-4"><p class="text-sm font-semibold">{{c.author}}</p><p class="mt-1 text-sm text-slate-600">{{c.body}}</p></div></UiCard></aside></div></div></AppShell></template>
